    "tipoNombre": "Licitación Pública >100 UTM",
    "titulo": "Habilitación Sala de Monitoreo y Punto de Cámaras",
    "organismo": "I MUNICIPALIDAD DE RECOLETA",
    "organismoRut": "69.254.800-0",
    "organismoPagoDias": null,
    "organismoRiesgo": "Sin evaluar",
    "rubro": "Tecnología y Hardware",
